// === E5-R4 Blueprint Intake: Validate ===
// Schema v1.0 validation — reject before any processing

const SCHEMA_VERSION = "1.0";
const ALLOWED_FIELDS = new Set([
  "schema_version", "request_id", "project_id", "project_name",
  "repository", "blueprint", "blueprint_sha256", "requested_capabilities",
  "target_environment", "dry_run", "constraints", "metadata"
]);
const ALLOWED_CAPABILITIES = new Set(["build", "test", "lint", "docs", "evidence", "review"]);
const MAX_BLUEPRINT = 300000;
const MAX_REQUEST = 500000;

const raw = $input.first().json.body || $input.first().json;
const errors = [];
const warnings = [];

// --- Size limit ---
const reqStr = JSON.stringify(raw);
if (reqStr.length > MAX_REQUEST) {
  errors.push({code: "REQUEST_TOO_LARGE", field: null});
}

// --- Unknown fields ---
for (const key of Object.keys(raw)) {
  if (!ALLOWED_FIELDS.has(key)) {
    errors.push({code: "UNKNOWN_FIELD", field: key, message: "Unknown field: " + key});
  }
}

// --- Schema version ---
const sv = raw.schema_version;
if (!sv) {
  errors.push({code: "MISSING_REQUIRED_FIELD", field: "schema_version"});
} else if (sv !== SCHEMA_VERSION) {
  errors.push({code: "INVALID_SCHEMA_VERSION", field: "schema_version", message: "Expected " + SCHEMA_VERSION + ", got " + sv});
}

// --- Required fields ---
for (const f of ["request_id", "project_id", "blueprint"]) {
  if (!raw[f]) {
    errors.push({code: "MISSING_REQUIRED_FIELD", field: f, message: f + " is required"});
  }
}

// --- Field validation ---
const requestId = String(raw.request_id || "");
const projectId = String(raw.project_id || "");
const blueprint = String(raw.blueprint || "");

if (requestId && !/^[a-z0-9][a-z0-9-]{2,62}$/.test(requestId)) {
  errors.push({code: "INVALID_REQUEST_ID", field: "request_id"});
}
if (projectId && !/^[a-z0-9][a-z0-9-]{2,62}$/.test(projectId)) {
  errors.push({code: "INVALID_PROJECT_ID", field: "project_id"});
}
if (blueprint.length < 50) {
  errors.push({code: "BLUEPRINT_TOO_SHORT", field: "blueprint"});
}
if (blueprint.length > MAX_BLUEPRINT) {
  errors.push({code: "BLUEPRINT_TOO_LONG", field: "blueprint"});
}

// --- Repository validation ---
const repo = String(raw.repository || "");
if (repo && !/^[a-zA-Z0-9]([a-zA-Z0-9._-]*[a-zA-Z0-9])?\/[a-zA-Z0-9]([a-zA-Z0-9._-]*[a-zA-Z0-9])?$/.test(repo)) {
  errors.push({code: "INVALID_REPOSITORY", field: "repository"});
}

// --- Blueprint SHA256 verification ---
const expectedSha = raw.blueprint_sha256 || "";
let shaVerified = false;
if (expectedSha) {
  const crypto = require('crypto');
  const actualSha = crypto.createHash('sha256').update(blueprint).digest('hex');
  if (actualSha !== expectedSha) {
    errors.push({code: "BLUEPRINT_HASH_MISMATCH", field: "blueprint_sha256"});
  } else {
    shaVerified = true;
  }
}

// --- Danger scan ---
const DANGER_PATTERNS = [
  [/\.\.\//, "PATH_TRAVERSAL"],
  [/\/etc\/passwd/, "SENSITIVE_FILE"],
  [/rm\s+-rf\s+\//, "DESTRUCTIVE_COMMAND"],
  [/curl.*\|.*sh/, "PIPE_TO_SHELL"],
  [/\$\(.*\)/, "SHELL_EXPANSION"],
  [/`[^`]+`/, "BACKTICK_EXECUTION"]
];
for (const [pat, code] of DANGER_PATTERNS) {
  if (pat.test(reqStr)) {
    errors.push({code: "DANGEROUS_" + code, field: null});
    break;
  }
}

// --- Secret scan ---
const SECRET_PATTERNS = [
  [/sk-[A-Za-z0-9]{20,}/, "OPENAI_API_KEY"],
  [/ghp_[A-Za-z0-9_]{20,}/, "GITHUB_TOKEN"],
  [/-----BEGIN\s+[A-Z\s]+PRIVATE\s+KEY-----/, "PRIVATE_KEY"]
];
for (const [pat, code] of SECRET_PATTERNS) {
  if (pat.test(blueprint)) {
    errors.push({code: "SECRET_" + code, field: "blueprint"});
    break;
  }
}

// --- Injection scan (warn, don't block) ---
const INJECTION_PATTERNS = [
  [/ignore\s+(all\s+)?(previous|prior|above)\s+(instructions|rules|constraints)/i, "INJECTION_IGNORE"],
  [/bypass\s+(security|verification|gate|policy)/i, "INJECTION_BYPASS"],
  [/disable\s+(verifier|security\s+gate)/i, "INJECTION_DISABLE"]
];
for (const [pat, code] of INJECTION_PATTERNS) {
  if (pat.test(blueprint)) {
    warnings.push({code: code, message: "Injection pattern detected — flagged not blocked"});
    break;
  }
}

// --- Capability validation ---
const caps = raw.requested_capabilities || [];
if (caps.length > 0) {
  if (!Array.isArray(caps)) {
    errors.push({code: "INVALID_CAPABILITIES", field: "requested_capabilities"});
  } else {
    for (const c of caps) {
      if (!ALLOWED_CAPABILITIES.has(c)) {
        errors.push({code: "UNKNOWN_CAPABILITY", field: "requested_capabilities", message: "Unknown: " + c});
      }
    }
  }
}

// --- Dry run enforcement ---
const isDryRun = raw.dry_run !== false;  // defaults to true

const valid = errors.length === 0;
const normalizedProjectId = projectId.toLowerCase().trim();

return [{
  json: {
    valid: valid,
    status: valid ? "VALID" : "REJECTED",
    errors: errors,
    warnings: warnings,
    normalized_project_id: normalizedProjectId,
    blueprint_length: blueprint.length,
    sha_verified: shaVerified,
    dry_run: isDryRun,
    // Preserve original for downstream
    raw_request_id: requestId,
    raw_project_id: projectId,
    raw_project_name: raw.project_name || projectId,
    raw_repository: repo || "synthetic/" + normalizedProjectId,
    raw_blueprint: blueprint,
    raw_blueprint_sha256: expectedSha,
    raw_capabilities: caps,
    raw_target: raw.target_environment || "auto"
  }
}];

// === E5-R4 Blueprint Intake: Registry Lookup ===
// Read-only query of GHIW registry via SSH
// Checks: project exists? builder exists? builder state?

const state = $input.first().json;
const projectKey = state.normalized_project_id;
const dryRun = state.dry_run;

// Build SSH command for read-only registry query
const queryCmd = `sqlite3 -readonly -json /var/lib/ghiw-provisioner/registry.sqlite3 \
  "SELECT builder_id, ctid, current_state FROM builders WHERE project_id='${projectKey}' LIMIT 1; \
   SELECT project_id, project_key, repository, current_state FROM projects WHERE project_key='${projectKey}' LIMIT 1;"`;

return [{
  json: {
    ...state,
    registry_query_cmd: queryCmd,
    registry_query_dry_run: dryRun
  }
}];

// === E5-R4 Blueprint Intake: Builder Decision ===
// Determines: WOULD_REUSE_EXISTING | WOULD_PROVISION_NEW | REJECTED
// DRY RUN: never calls op_ensure_builder or writes registry

const state = $input.first().json;
const valid = state.valid;
const dryRun = state.dry_run;

// Parse registry query result
let projectExists = false;
let builderExists = false;
let builderId = null;
let builderCtid = null;
let builderState = null;

try {
  const stdout = state.stdout || "";
  // SQLite -json returns JSON arrays per SELECT
  const parts = stdout.split(/\n(?=\[)/);
  if (parts.length >= 2) {
    const builders = JSON.parse(parts[1]);  // First SELECT: builders
    const projects = JSON.parse(parts[2]);  // Second SELECT: projects
    if (builders && builders.length > 0) {
      builderExists = true;
      builderId = builders[0].builder_id;
      builderCtid = builders[0].ctid;
      builderState = builders[0].current_state;
    }
    if (projects && projects.length > 0) {
      projectExists = true;
    }
  }
} catch(e) {
  // Parse failure = no registry entries
}

let decision = "REJECTED";
let decisionDetail = "";
let wouldMutation = false;

if (!valid) {
  decision = "REJECTED";
  decisionDetail = "Blueprint validation failed: " + (state.errors || []).map(e => e.code).join(", ");
} else if (builderExists && builderState === "BUILDER_READY") {
  decision = "WOULD_REUSE_EXISTING";
  decisionDetail = "Existing BUILDER_READY found: " + builderId + " (CT " + builderCtid + ")";
} else if (projectExists && (!builderExists || builderState !== "BUILDER_READY")) {
  decision = "WOULD_PROVISION_NEW";
  decisionDetail = "Project exists but no READY builder. Would provision new builder.";
  wouldMutation = true;
} else if (!projectExists) {
  decision = "WOULD_PROVISION_NEW";
  decisionDetail = "New project: " + state.normalized_project_id + ". Would create project + provision builder.";
  wouldMutation = true;
}

// Hard dry-run guard
let mutationBlocked = false;
if (wouldMutation && dryRun) {
  mutationBlocked = true;
  decisionDetail += " [DRY_RUN: mutation blocked]";
}
if (wouldMutation && !dryRun) {
  decisionDetail += " [LIVE: would execute mutation]";
}

const result = {
  // Input
  request_id: state.raw_request_id,
  project_id: state.normalized_project_id,
  blueprint_length: state.blueprint_length,
  dry_run: dryRun,
  valid: valid,

  // Registry state
  project_exists: projectExists,
  builder_exists: builderExists,
  builder_id: builderId,
  builder_ctid: builderCtid,
  builder_state: builderState,

  // Decision
  decision: decision,
  decision_detail: decisionDetail,
  would_mutate: wouldMutation,
  mutation_blocked_by_dry_run: mutationBlocked,

  // Safety
  errors: state.errors || [],
  warnings: state.warnings || [],

  // Execution context
  workflow_id: $workflow.id,
  execution_id: $execution.id,
  timestamp: new Date().toISOString()
};

return [{ json: result }];

// === E5-R4 Blueprint Intake: Format Result ===
const state = $input.first().json;

// Build deterministic dry-run result
const dryRunResult = {
  schema_version: "1.0",
  workflow: "GHIW Blueprint Intake (DRY RUN)",
  status: state.decision,
  request_id: state.request_id,
  project_id: state.project_id,
  dry_run: state.dry_run,
  result: {
    valid: state.valid,
    decision: state.decision,
    detail: state.decision_detail,
    project_exists: state.project_exists,
    builder_exists: state.builder_exists,
    builder_id: state.builder_id || null,
    builder_ctid: state.builder_ctid || null,
    builder_state: state.builder_state || null,
    would_mutate: state.would_mutate,
    mutation_blocked_by_dry_run: state.mutation_blocked_by_dry_run || false
  },
  errors: state.errors,
  warnings: state.warnings || [],
  execution: {
    workflow_id: state.workflow_id,
    execution_id: state.execution_id,
    timestamp: state.timestamp
  },
  safety: {
    dry_run_enforced: state.dry_run,
    no_mutations_performed: true,
    registry_read_only: true
  }
};

return [{ json: dryRunResult }];

// === E5-R4 Blueprint Intake: Error Handler ===
// SSH failure or validation failure path
const state = $input.first().json || {};

let errors = [];
if (state.errors) {
  errors = state.errors;
} else if (state.stdout) {
  // SSH failed but we had prior state
  errors = [{code: "SSH_REGISTRY_QUERY_FAILED", message: String(state.stdout || "").slice(0, 200)}];
} else {
  errors = [{code: "UNKNOWN_ERROR", message: "Blueprint intake failed"}];
}

const result = {
  schema_version: "1.0",
  workflow: "GHIW Blueprint Intake (DRY RUN)",
  status: "ERROR",
  dry_run: true,
  result: {
    valid: false,
    decision: "ERROR",
    detail: "Registry query or validation failed",
    would_mutate: false,
    mutation_blocked_by_dry_run: true
  },
  errors: errors,
  execution: {
    workflow_id: $workflow.id,
    execution_id: $execution.id,
    timestamp: new Date().toISOString()
  },
  safety: {
    dry_run_enforced: true,
    no_mutations_performed: true
  }
};

return [{ json: result }];
